  "無法帶入主畫面音樂：{0}": { en: "Unable to import main-screen audio: {0}", ja: "メイン画面の音楽を読み込めません：{0}", fr: "Impossible d’importer l’audio de l’écran principal : {0}", de: "Audio der Hauptansicht kann nicht übernommen werden: {0}", it: "Impossibile importare l’audio della schermata principale: {0}", es: "No se pudo importar el audio de la pantalla principal: {0}" },
  "已恢復分離後的原始人聲。": { en: "Restored the original separated vocals.", ja: "分離後の元のボーカルに戻しました。", fr: "Les voix séparées d’origine ont été restaurées.", de: "Der ursprüngliche getrennte Gesang wurde wiederhergestellt.", it: "Ripristinata la voce originale separata.", es: "Se restauró la voz original separada." },
