  "已恢復原始人聲。": { en: "Original vocals restored.", ja: "元のボーカルに戻しました。", fr: "Voix d’origine restaurées.", de: "Originalgesang wiederhergestellt.", it: "Voce originale ripristinata.", es: "Voz original restaurada." },
