  "自動調音失敗。": { en: "Auto-tuning failed.", ja: "自動チューニングに失敗しました。", fr: "Échec de la correction automatique.", de: "Auto-Tuning fehlgeschlagen.", it: "Intonazione automatica non riuscita.", es: "Falló la afinación automática." },
