  "推論結果無效": { en: "invalid inference result", ja: "推論結果が無効", fr: "résultat d’inférence invalide", de: "ungültiges Inferenzergebnis", it: "risultato di inferenza non valido", es: "resultado de inferencia no válido" },
  "GPU 分離結果無效，正在自動改用 CPU 重新處理…": { en: "GPU separation result is invalid; retrying automatically on CPU…", ja: "GPU 分離結果が無効です。CPU に自動で切り替えて再処理しています…", fr: "Le résultat de séparation GPU est invalide ; nouvelle tentative automatique sur le processeur…", de: "GPU-Trennungsergebnis ungültig; automatischer erneuter Versuch mit CPU…", it: "Risultato della separazione GPU non valido; nuovo tentativo automatico con CPU…", es: "El resultado de separación de GPU no es válido; reintentando automáticamente con CPU…" },
  "無效的分離音軌。": { en: "Invalid separated audio track.", ja: "分離音声トラックが無効です。", fr: "Piste audio séparée non valide.", de: "Ungültige getrennte Audiospur.", it: "Traccia audio separata non valida.", es: "Pista de audio separada no válida." },
  "分離音軌資料不完整，請重新執行人聲分離。": { en: "Separated track data is incomplete. Run vocal separation again.", ja: "分離音声のデータが不完全です。ボーカル分離をもう一度実行してください。", fr: "Les données des pistes séparées sont incomplètes. Relancez la séparation vocale.", de: "Die Daten der getrennten Spuren sind unvollständig. Führe die Vocal-Trennung erneut aus.", it: "I dati delle tracce separate sono incompleti. Esegui di nuovo la separazione vocale.", es: "Los datos de las pistas separadas están incompletos. Vuelve a ejecutar la separación vocal." },
