  "左右聲道長度不一致。": { en: "Left and right channel lengths do not match.", ja: "左右チャンネルの長さが一致しません。", fr: "Les longueurs des canaux gauche et droit ne correspondent pas.", de: "Die Längen des linken und rechten Kanals stimmen nicht überein.", it: "Le lunghezze dei canali sinistro e destro non corrispondono.", es: "La duración de los canales izquierdo y derecho no coincide." },
  "Spleeter 模型輸出形狀不符。": { en: "Spleeter model output shape mismatch.", ja: "Spleeter モデルの出力形状が一致しません。", fr: "La forme de sortie du modèle Spleeter ne correspond pas.", de: "Die Ausgabeform des Spleeter-Modells stimmt nicht überein.", it: "La forma dell’output del modello Spleeter non corrisponde.", es: "La forma de salida del modelo Spleeter no coincide." },
  "Spleeter 模型產生無效數值。": { en: "The Spleeter model produced invalid values.", ja: "Spleeter モデルから無効な値が出力されました。", fr: "Le modèle Spleeter a produit des valeurs non valides.", de: "Das Spleeter-Modell hat ungültige Werte erzeugt.", it: "Il modello Spleeter ha prodotto valori non validi.", es: "El modelo Spleeter generó valores no válidos." },
  "人聲 WAV 格式不正確，請重新執行人聲分離。": { en: "The vocal WAV format is invalid. Run vocal separation again.", ja: "ボーカル WAV の形式が正しくありません。ボーカル分離をもう一度実行してください。", fr: "Le format WAV des voix est incorrect. Relancez la séparation vocale.", de: "Das Vocal-WAV-Format ist ungültig. Führe die Vocal-Trennung erneut aus.", it: "Il formato WAV della voce non è corretto. Esegui di nuovo la separazione vocale.", es: "El formato WAV de voz no es válido. Vuelve a ejecutar la separación vocal." },
  "自動調音目前只支援 16-bit 立體聲 PCM WAV。": { en: "Auto-tuning currently supports only 16-bit stereo PCM WAV.", ja: "自動チューニングが現在対応しているのは 16-bit ステレオ PCM WAV のみです。", fr: "La correction automatique ne prend actuellement en charge que le WAV PCM stéréo 16 bits.", de: "Auto-Tuning unterstützt derzeit nur 16-Bit-Stereo-PCM-WAV.", it: "L’intonazione automatica supporta attualmente solo WAV PCM stereo a 16 bit.", es: "La afinación automática solo admite WAV PCM estéreo de 16 bits." }
,
  "取消 MUTE": { en: "Unmute", ja: "ミュート解除", fr: "Activer le son", de: "Stummschaltung aufheben", it: "Riattiva audio", es: "Quitar silencio" },
  "目前瀏覽器無法啟用音量與 EQ 處理，音軌將使用原始聲音播放。": { en: "This browser cannot enable volume and EQ processing; the track will play in its original form.", ja: "このブラウザーでは音量と EQ 処理を有効にできないため、音軌は元の音で再生されます。", fr: "Ce navigateur ne peut pas activer le traitement du volume et de l’EQ ; la piste sera lue telle quelle.", de: "Dieser Browser kann Lautstärke- und EQ-Verarbeitung nicht aktivieren; die Spur wird im Original wiedergegeben.", it: "Questo browser non può attivare volume ed EQ; la traccia verrà riprodotta senza modifiche.", es: "Este navegador no puede activar el procesamiento de volumen y EQ; la pista se reproducirá tal cual." },
  "目前瀏覽器無法同步播放兩條音軌。": { en: "This browser cannot play both tracks in sync.", ja: "このブラウザーでは 2 つの音軌を同期再生できません。", fr: "Ce navigateur ne peut pas lire les deux pistes en synchronisation.", de: "Dieser Browser kann beide Spuren nicht synchron abspielen.", it: "Questo browser non può riprodurre entrambe le tracce in sincrono.", es: "Este navegador no puede reproducir ambas pistas sincronizadas." },
  "同步暫停": { en: "Pause synchronized playback", ja: "同期再生を一時停止", fr: "Mettre en pause la lecture synchronisée", de: "Synchronisierte Wiedergabe pausieren", it: "Metti in pausa la riproduzione sincronizzata", es: "Pausar reproducción sincronizada" },
  "WebGPU GPU 加速（FP32）": { en: "WebGPU acceleration (FP32)", ja: "WebGPU GPU 高速化（FP32）", fr: "Accélération WebGPU (FP32)", de: "WebGPU-Beschleunigung (FP32)", it: "Accelerazione WebGPU (FP32)", es: "Aceleración WebGPU (FP32)" },
  "重新自動調音": { en: "Auto-tune again", ja: "再度自動チューニング", fr: "Relancer la correction automatique", de: "Auto-Tuning erneut ausführen", it: "Ripeti l’intonazione automatica", es: "Volver a afinar automáticamente" }
,
